using Estate.Contracts;
using Estate.Payments.Data;

namespace Estate.Payments
{
    /// <summary>The on-prem WCF payment service. Posting goes through a stored procedure; lookups go through Entity Framework.</summary>
    public class PaymentService : IPaymentService
    {
        public PaymentResult Post(PaymentRequest request)
        {
            using (var db = new PaymentsContext())
            {
                PostPaymentRow row = db.PostPayment(request.AccountNumber, request.Amount);
                return new PaymentResult
                {
                    PaymentId      = row.PaymentId,
                    Status         = row.Status,
                    AccountBalance = row.AccountBalance
                };
            }
        }

        public PaymentResult Get(PaymentQuery query)
        {
            using (var db = new PaymentsContext())
            {
                Payment payment = db.Payments.Find(query.PaymentId);
                if (payment == null)
                {
                    return null;
                }
                return new PaymentResult
                {
                    PaymentId      = payment.PaymentId,
                    Status         = payment.Status,
                    AccountBalance = 0m
                };
            }
        }
    }
}
using System;
using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;

namespace Estate.Payments.Data
{
    /// <summary>A row of dbo.Payment.</summary>
    [Table("Payment", Schema = "dbo")]
    public class Payment
    {
        [Key]
        public string   PaymentId     { get; set; }
        public string   AccountNumber { get; set; }
        public decimal  Amount        { get; set; }
        public string   Status        { get; set; }
        public DateTime PostedAt      { get; set; }
    }
}
using System.Data.Entity;
using System.Data.SqlClient;
using System.Linq;

namespace Estate.Payments.Data
{
    /// <summary>
    /// Entity Framework context over the on-prem Payments database. The connection string
    /// is App.config's "PaymentsDb". Posting a payment calls dbo.usp_PostPayment, which is
    /// where the linked-server read of the Oracle account balance happens.
    /// </summary>
    public class PaymentsContext : DbContext
    {
        public const string ConnectionName       = "PaymentsDb";
        public const string PostPaymentProcedure = "dbo.usp_PostPayment";

        public PaymentsContext() : base("name=" + ConnectionName)
        {
        }

        public DbSet<Payment> Payments { get; set; }

        public PostPaymentRow PostPayment(string accountNumber, decimal amount)
        {
            return Database.SqlQuery<PostPaymentRow>(
                "EXEC " + PostPaymentProcedure + " @AccountNumber, @Amount",
                new SqlParameter("@AccountNumber", accountNumber),
                new SqlParameter("@Amount",        amount)).Single();
        }
    }
}
namespace Estate.Payments.Data
{
    /// <summary>The single row dbo.usp_PostPayment returns.</summary>
    public class PostPaymentRow
    {
        public string  PaymentId      { get; set; }
        public string  Status         { get; set; }
        public decimal AccountBalance { get; set; }
    }
}
<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <TargetFramework>net48</TargetFramework>
    <LangVersion>10.0</LangVersion>
    <ImplicitUsings>disable</ImplicitUsings>
    <Nullable>disable</Nullable>
  </PropertyGroup>
  <ItemGroup>
    <Reference Include="System.ServiceModel" />
    <Reference Include="System.Data" />
    <Reference Include="System.ComponentModel.DataAnnotations" />
  </ItemGroup>
  <ItemGroup>
    <PackageReference Include="EntityFramework" Version="6.5.1" />
  </ItemGroup>
  <ItemGroup>
    <ProjectReference Include="../Contracts/Contracts.csproj" />
  </ItemGroup>
</Project>
<?xml version="1.0" encoding="utf-8"?>
<configuration>
  <connectionStrings>
    <add name="PaymentsDb"
         connectionString="Server=sql.onprem.example;Database=Payments;Integrated Security=true"
         providerName="System.Data.SqlClient" />
  </connectionStrings>
  <system.serviceModel>
    <services>
      <service name="Estate.Payments.PaymentService">
        <endpoint address="net.tcp://payments.onprem.example:8732/PaymentService"
                  binding="netTcpBinding" contract="Estate.Contracts.IPaymentService" />
      </service>
    </services>
  </system.serviceModel>
</configuration>
using System.ServiceModel;

namespace Estate.Contracts
{
    /// <summary>The payment service's contract, one deployment per workload and environment.</summary>
    [ServiceContract(Namespace = "http://estate.example/payments/service")]
    public interface IPaymentService
    {
        [OperationContract]
        PaymentResult Post(PaymentRequest request);

        [OperationContract]
        PaymentResult Get(PaymentQuery query);
    }
}
